T.usage["surface"] = "Ground of every panel, tooltip and menu. In-game it sits at 90% over the world: use surface-glass there."
T.usage["surface-glass"] = "Panels floating over the 3D world (Panel, Tooltip, action bar dock). Text on it follows the surface rules."
T.usage["surface-sunk"] = "The empty part of a unit bar, cast bar track and icon wells. The bar IS the frame: no extra backdrop around it."
T.usage["surface-raised"] = "Buttons, action button wells, hovered rows."
T.usage["track"] = "Thin tracks under 2–6px bars (power line, drain lines, XP and reputation bars)."
T.usage["world"] = "Stand-in for the game world behind previews and mockups. Never ship it in-game."
T.usage["gilt"] = "Ornament only: diamond corners, the divider jewel, the minimap ring and north marker. Never a state, never body text."
T.usage["gilt-text"] = "Panel titles, section headers and the active tab, set in `header`, on surface, surface-glass and surface-sunk (11.9:1)."
T.usage["gilt-line"] = "1px borders of panels and anchors (player frame, minimap, action bar)."
T.usage["gilt-hairline"] = "1px border of every unit bar, aura and cooldown icon at rest, and of common-quality item slots."
T.usage["gilt-faint"] = "Row dividers inside panels; the border of an empty item slot; the dashed border of an icon whose data is unavailable and of an empty totem slot."
T.usage["ink"] = "Primary text and numbers on surface, surface-glass, surface-sunk, surface-raised (≥14.7:1) and on unit-fill / unit-fill-low (≥4.8:1)."
T.usage["ink-muted"] = "Secondary text (class, subtitles, meta, chat timestamps) on surface and surface-sunk (6.8:1). Never on a health fill (2.1:1)."
T.usage["ink-faint"] = "Disabled and dead units only (3.9:1 on surface — below 4.5:1 on purpose: disabled text is exempt)."
T.usage["unit-fill"] = "Healthy health fill (right end of the gradient from unit-fill-deep). Neutral on purpose: health is not a state until it is low. 3.05:1 against surface-sunk."
T.usage["unit-fill-deep"] = "Left end of the healthy health-fill gradient."
T.usage["unit-fill-low"] = "Health fill below the low threshold (35%), right end of the gradient from unit-fill-low-deep. ink on it 4.8:1."
T.usage["unit-fill-low-deep"] = "Left end of the low-health gradient."
T.usage["ghost"] = "Recent damage: the segment the fill just lost, drained away by motion after the truth has already updated."
T.usage["arcane"] = "READY / ACTIONABLE: a cooldown that is up, an interruptible cast, the suggested action, your own position, a quest ready to turn in, an unspent point in the micro menu. As text, on surface and surface-sunk (10.4:1)."
T.usage["arcane-soft"] = "Well behind arcane icons and the suggested action button."
T.usage["arcane-glow"] = "Glow around ready icons and the interruptible cast bar. Glows only ever come in a state colour."
T.usage["ember"] = "DANGER: aggro on a non-tank, a tank losing a mob for good, low health, a lethal cast. Borders, badge fills, the alert hairlines. As text use ember-text."
T.usage["ember-text"] = "Danger text (alert titles, low-health %) on surface, surface-sunk and ember-soft (≥8.5:1)."
T.usage["ember-soft"] = "Ground of the danger Alert."
T.usage["amber"] = "WARNING: low mana, an expiring aura, threat closing in (a tank about to lose a mob), a timeline ability under 5 seconds. As text on surface (10.4:1)."
T.usage["fel"] = "HEALING: incoming heals and heal-over-time drain lines. Never a 'success' colour for UI chrome."
T.usage["fel-incoming"] = "Incoming-heal segment after the health fill (3.3:1 against surface-sunk): present, never louder than the health itself."
T.usage["ward"] = "PROTECTED: a big defensive, an external (Blessing of Protection, Pain Suppression) or a shield is active. Border of the warded unit and of defensive aura icons."
T.usage["ward-absorb"] = "Absorb-shield segment on the health bar, hatched."
T.usage["dispel-magic"] = "Magic debuff you can remove: unit border, debuff icon border, badge fill."
T.usage["dispel-curse"] = "Curse debuff you can remove."
T.usage["dispel-poison"] = "Poison debuff you can remove."
T.usage["dispel-disease"] = "Disease debuff you can remove."
T.usage["on-signal"] = "Text and glyphs on any signal fill (ember, amber, arcane, ward, the dispel colours, gilt-text): ≥6.1:1 on all of them. Never white."
T.usage["mana"] = "Mana power line."
T.usage["rage"] = "Rage power line."
T.usage["energy"] = "Energy power line."
T.usage["focus"] = "Focus power line (hunter pets). 4.2:1 against track."
T.usage["progress-fill"] = "XP and reputation fill. Neutral on purpose: progress is not a state. 3.9:1 against track."
T.usage["progress-rested"] = "Rested XP: the hatched segment after the XP fill."
T.usage["class-warrior"] = "Class chip (the 5px diamond before a name, on unit frames, the minimap and in chat). Class colours are identity, never state, never a whole bar (one opt-in exception: the damage meter's class-coloured bars, darkened so ink names stay readable)."
T.usage["class-paladin"] = "Class chip."
T.usage["class-hunter"] = "Class chip."
T.usage["class-rogue"] = "Class chip."
